"""Source-selection student experience, real excerpts and reproducible docs."""
STYLE+='''body{overflow-wrap:anywhere}.control-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}select{width:100%;font:700 20px/1.5 "Segoe UI",Arial;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink)}.workspace{margin:24px 0}.json-view{max-height:480px}.markdown-body{white-space:normal!important}.markdown-body li{margin:12px 0}.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.table{max-width:100%}#notice:empty{display:none}#fixture-content{white-space:pre-wrap;color:var(--ink);font-family:Consolas,"Cascadia Code",monospace;font-size:20px;line-height:1.6;padding:24px;border:1px solid var(--line);border-radius:16px;background:var(--soft);max-height:420px;overflow:auto}.workflow-step{scroll-margin-top:20px}@media(max-width:850px){.control-grid,.stats{grid-template-columns:1fr}}'''
(PUBLIC/'style.css').write_text(STYLE,encoding='utf-8')
learn=[('Select three filesystem sources','user, project and local load different settings/instruction locations. The experiment creates safe fixtures in a private project and private SDK config home.'),('Distinguish omission from []','With the pinned TypeScript SDK, omission loads all three sources. [] skips them. A listed subset opts in only to the named sources; the app preserves that distinction in its actual options.'),('Observe loaded instructions','Compare returned project, user and local instruction markers without supplying them in the prompt. The model can Read only data.md, so it cannot fetch the instruction files with a tool. Compliance is an observation, not a complete configuration audit.'),('Compare two hook mechanisms','A trusted command hook from project settings writes a private trace. A programmatic PreToolUse callback guards the data Read and runs even when filesystem sources are [].'),('Know the limits of source filtering','Managed policy, global config, auto memory, authenticated connectors and sandbox credential restrictions have separate behavior. [] alone is not complete isolation.'),('Build explicit classroom configurations','The Alpha and Beta examples use distinct owned cwd, home and config directories, [], disabled auto memory and strict MCP config. Shared-machine directories and hooks are not a production OS or tenant sandbox.')]
body='''<div class="flow"><div><b>01 · Select</b><p>Explicit sources or omission</p></div><span>→</span><div><b>02 · Load</b><p>Trusted classroom fixtures</p></div><span>→</span><div><b>03 · Verify</b><p>Returned markers and hook traces</p></div></div><section class="panel" id="controls"><h2>Which filesystem sources will this agent use?</h2><p class="meta" id="configuration">Checking server configuration…</p><div class="control-grid"><div><label for="mode">Source selection</label><select id="mode"><option value="project">Project only · ["project"]</option><option value="none">No filesystem sources · []</option><option value="combined">User + project · ["user", "project"]</option><option value="defaults">Omit settingSources · runtime defaults</option><option value="tenant">Private classroom directory configuration · []</option></select></div><div><label for="tenant">Classroom directory ID</label><select id="tenant"><option value="alpha">Alpha</option><option value="beta">Beta</option></select></div></div><p class="note">Same task: Read data.md, summarize its two bullets, report any workspace marker in that data, and follow classroom instructions already loaded into context. The prompt contains no rule-marker values. Instruction/configuration files are blocked as model tool reads.</p><button class="primary" id="run" disabled>Run the source comparison →</button><p class="meta">Every run prepares only trusted app-owned fixtures. Filesystem project hooks execute a fixed Node script; no model Bash tool is available. All examples disable auto memory and use a private home/config directory for controlled comparisons.</p></section>
<div class="workspace"><section class="panel" id="outcome"><div class="eyebrow">ACTUAL SDK RESULT</div><h2 id="status" aria-live="polite">Ready</h2><div class="stats"><div class="stat"><span>Estimated cost</span><strong id="cost">—</strong></div><div class="stat"><span>Programmatic callback count</span><strong id="callback-count">0</strong></div><div class="stat"><span>Filesystem hook records</span><strong id="filesystem-count">0</strong></div></div><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{ "state": "Waiting for a run" }</code></pre><p class="meta">The omitted case has no settingSources property. Safe path aliases and environment flags are shown; inherited credentials and raw environment values are not.</p></section></div>
<section class="step" id="instruction-panel"><h2>Instruction markers actually returned</h2><pre><code id="markers" class="language-json">[]</code></pre><p>Completed model Read paths: <strong id="read-paths">No evidence yet</strong></p><p class="meta">Markers come from the actual final text. They are not inserted into the prompt or replaced with expected answers. Model compliance can vary; a missing marker alone does not prove a file was absent. The independent filesystem-hook trace below records merged fixture environment flags.</p></section>
<section class="step" id="hooks-panel"><h2>Filesystem command hook · actual private trace</h2><pre class="json-view"><code id="filesystem-hooks" class="language-json">[]</code></pre><p class="meta">Only project settings define this SessionStart command hook. Its trusted script records the event and harmless user/project/local environment flags in hook-evidence.json. An empty trace means no filesystem hook record was observed in this run; it does not mean the host has no managed configuration.</p></section>
<section class="step" id="callback-panel"><h2>Programmatic hooks remain explicit</h2><ul id="callbacks"></ul><p class="meta">The actual PreToolUse callback is passed in code. It guards the Read regardless of source selection, including []. The filesystem hook runs at SessionStart; these are two mechanisms in the same session, not a claim that every hook type executes the same event.</p></section>
<section class="step" id="fixtures-panel"><h2>Trusted classroom configuration files</h2><label for="fixture">Inspect the fixture</label><select id="fixture"></select><p class="source" id="fixture-source"></p><div id="fixture-content" role="region" aria-label="Trusted fixture file content">Run an experiment to inspect its prepared files.</div><p class="meta">This panel is a host-rendered view for the student. It is not sent to the model as a prompt or tool result. CLAUDE.md instructions are non-conflicting. The small project rules file is an illustrative helper rule; the marker exercise tests the three CLAUDE instruction layers.</p></section>
<section class="step" id="directory-panel"><h2>Private classroom directory configuration</h2><pre class="json-view"><code id="directories" class="language-json">{ "state": "Waiting for a run" }</code></pre><p class="meta">Alpha and Beta resolve to distinct owned project, home and SDK-config directories. The tenant exercise uses [], auto-memory disabled and strict MCP config. The actual data read returns its Alpha/Beta workspace marker. This is a directory-configuration demonstration on one machine, not proof of secure production tenant isolation or removal of organization policy.</p></section>
<section class="step" id="event-panel"><h2>Actual messages and tool requests</h2><ul id="events"></ul></section><section class="step" id="run-history"><h2>Compare the observed runs</h2><div class="table"><table><thead><tr><th>Mode</th><th>Directory ID</th><th>Returned rule markers</th><th>Callback count</th><th>Filesystem records</th><th>Result</th><th>Session</th></tr></thead><tbody id="history"></tbody></table></div></section><section class="step" id="init-panel"><h2>Actual system/init</h2><pre><code id="init" class="language-json">{ "state": "Waiting for init" }</code></pre></section><section class="note"><h3>What this comparison does not prove</h3><p>Managed host/server policy, global config behavior, live authenticated connectors, sandbox credential denies, parent-directory discovery, skills, commands and subagents are reference topics. No policies are removed or bypassed. No production tenant isolation is claimed. Source selection adds context and may add token cost; estimates vary. The model Read guard and owned directories are application controls, not an OS sandbox.</p></section><button id="download">Download actual observations</button>'''
document('/','Select the sources. <em>Observe what loads.</em>','Compare actual instructions, filesystem settings and programmatic hooks with explicit private classroom configurations.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you will <em>learn.</em>','Make the difference between a selected source, an observed instruction and an independent hook trace visible.',cards(learn)+actions(('/run.html','Configure and run →'),('/architecture.html','Architecture →')))
setup='cd .\\agent-sdk\\lesson13-setting-sources\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n# http://127.0.0.1:3113'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3113'
runsteps=[('Check prerequisites','Use Node.js 24+, npm and an Anthropic key with access to the configured model. Keep optional dependencies enabled. This app pins TypeScript SDK 0.3.310; Python is not needed to run it.',''),('Install, configure and start','From presentations use the commands below. Preserve an existing .env or copy the safe template. Enter your key locally and restart after edits. The scripts explicitly load the optional file; shell variables take precedence.',snippet(setup,'powershell')+snippet(env,'dotenv')),('Run project-only sources','Keep Project only and Alpha. Run once. Inspect the actual project instruction marker, project filesystem hook record and programmatic Read callback. The trusted command trace should show project enabled, without user/local fixture flags.',''),('Compare with an empty source list','Select No filesystem sources and repeat the same task. Inspect [] in the actual options, no returned fixture rule markers, no filesystem hook record and an actual programmatic callback. The model is still allowed to Read data.md; [] does not erase the whole machine’s configuration.',''),('Select user plus project','Run User + project. Observe both corresponding instruction markers and environment flags. Local is not selected. Compare the actual response, filesystem trace and callback evidence rather than replacing them with an expected answer.',''),('Omit the option explicitly','Run Omit settingSources. The property is genuinely absent in the object, rather than passed as []. With the pinned runtime the user, project and local fixtures load. Observe the local instruction marker and local trace flag in addition to the other layers.',''),('Compare two private classroom directories','Choose Private classroom directory configuration, run Alpha, then Beta. Each has distinct owned cwd/home/config paths, [], disabled auto memory and strict MCP config. Confirm the workspace marker from each actual data read. These shared-machine directories do not establish production isolation.',''),('Inspect files, use the terminal and troubleshoot','Use the fixture selector to read the safe host view; it is not supplied to the agent prompt. Run CLI and web experiments sequentially. Configure the actual Git Bash path on Windows if requested. Keep the server terminal open and use Ctrl+C to stop it. A second start recognizes this app; choose another PORT for an unrelated listener. Unexpected markers or hook failures remain actual outcomes to investigate.',snippet('npm run sample:env -- project\nnpm run sample:env -- none\nnpm run sample:env -- combined\nnpm run sample:env -- defaults\nnpm run sample:env -- tenant alpha\nnpm run sample:env -- tenant beta\nnpm test','powershell'))]
body=''.join(f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{escape(t)}</h2><p>{escape(d)}</p>{c}</section>' for i,(t,d,c) in enumerate(runsteps,1))
document('/run.html','Configure and <em>run the source lab.</em>','Repeat the same task with selected, empty and omitted sources, then compare private classroom directories.',body+actions(('/learn.html','← Learning goals'),('/','Open the lab →')))
specs=[
 ('Validate source mode and classroom ID','src/server.ts','const config = validateConfig(input);','const config = validateConfig(input);','Accept only a listed source mode and Alpha/Beta ID. The browser cannot provide an arbitrary path or executable hook command.',0,1),
 ('Resolve owned cwd, home and config paths','src/agent.ts','const root = resolve(ROOT, ".runtime", config.mode, config.tenant);','const root = resolve(ROOT, ".runtime",\n  config.mode, config.tenant);\nreturn { root, cwd: resolve(root, "project"),\n  home: resolve(root, "home"),\n  sdkHome: resolve(root, "sdk-home") };','Resolve separate classroom directories. This path factory demonstrates deliberate configuration, not OS-enforced tenant isolation.',1,4),
 ('Prepare non-conflicting instruction fixtures','src/agent.ts','for (const file of files) await writeFile(file.path, file.contents);','for (const file of files)\n  await writeFile(file.path, file.contents);','Write trusted project, private-user and local fixtures before the query. The student sees a host-rendered file view; those file contents are not inserted into the model prompt.',1,4),
 ('Choose explicit sources or omission','src/agent.ts','if (mode === "defaults") return undefined;','if (mode === "defaults") return undefined;\nif (mode === "project") return ["project"];\nif (mode === "combined") return ["user", "project"];\nreturn [];','Preserve the semantic difference between an omitted option and an empty list. The pinned runtime loads all three sources when the option is omitted.',1,2),
 ('Leave the property absent when omitted','src/agent.ts','...(selected === undefined ? {} : { settingSources: selected }),','...(selected === undefined\n  ? {} : { settingSources: selected }),','The defaults experiment truly omits settingSources. Other modes pass their selected array, including an explicit empty array.',1,2),
 ('Configure memory and private context separately','src/agent.ts','CLAUDE_CONFIG_DIR: dirs.sdkHome, CLAUDE_CODE_DISABLE_AUTO_MEMORY: "1", ENABLE_CLAUDEAI_MCP_SERVERS: "false" },','env: { ...env,\n  HOME: dirs.home, USERPROFILE: dirs.home,\n  CLAUDE_CONFIG_DIR: dirs.sdkHome,\n  CLAUDE_CODE_DISABLE_AUTO_MEMORY: "1",\n  ENABLE_CLAUDEAI_MCP_SERVERS: "false"\n},','Source filtering does not control every input. The app explicitly relocates its config/home, disables auto memory and uses strict MCP config. Managed policy still has its own scope.',1,2),
 ('Start the same real task with selected options','src/agent.ts','const run = query({ prompt: PROMPTS.task, options });','const run = query({\n  prompt: PROMPTS.task, options\n});','The fixed prompt does not contain rule-marker values. The SDK loads the selected filesystem context and owns the model/tool loop.',1,2),
 ('Run the loaded filesystem command hook','fixtures/record-hook.cjs','event: input.hook_event_name,','records.push({\n  source: "filesystem command hook",\n  event: input.hook_event_name,\n  user: process.env.LESSON13_FROM_USER || null,\n  project: process.env.LESSON13_FROM_PROJECT || null,\n  local: process.env.LESSON13_FROM_LOCAL || null,\n});','Only project settings register this trusted SessionStart command. Its actual private trace records harmless merged fixture flags, independent of model prose.',2,3),
 ('Run the explicit programmatic callback','src/agent.ts','emit({ type: "callback", event: "PreToolUse", source: "programmatic" });','counters.callbacks++;\nemit({ type: "callback",\n  event: "PreToolUse", source: "programmatic"\n});','The callback passed in code guards the model Read and runs even with []. Filesystem and programmatic hooks are distinct mechanisms in the same session.',2,1),
 ('Block tool reads of instruction files','src/agent.ts','resolve(directories(config).cwd, "data.md").toLowerCase();','return name === "Read"\n  && typeof input.file_path === "string"\n  && resolve(directories(config).cwd, input.file_path)\n    .toLowerCase() === resolve(\n      directories(config).cwd, "data.md"\n    ).toLowerCase();','Only data.md can be read by the model tool. The agent cannot fetch instruction files to imitate source loading. Internal configuration loading is separate from model tool calls.',1,3),
 ('Preserve the actual typed result','src/agent.ts','resultText = redact(message.subtype === "success" ? message.result :','resultText = redact(message.subtype === "success"\n  ? message.result : message.errors.join("\\n"));','Store the actual final text and subtype. Marker extraction reflects model compliance; it is not a complete audit of all filesystem or policy inputs.',2,1),
 ('Read the private filesystem trace','src/agent.ts','const filesystemHooks = JSON.parse(await readFile(resolve(directories(config).cwd, "hook-evidence.json"), "utf8"));','const filesystemHooks = JSON.parse(await readFile(\n  resolve(directories(config).cwd, "hook-evidence.json"),\n  "utf8"\n));','After closing the query, read the actual hook trace and retain callback count and completed model Read paths. Empty filesystem evidence is kept as an empty trace.',3,1),
 ('Format and compare independent observations','src/client.ts','if (e.type === "answer") renderMarkdown($("answer"), e.text);','if (e.type === "answer")\n  renderMarkdown($("answer"), e.text);','Render actual answers through bundled Markdown parsing and sanitization. Keep options, returned markers, hook traces and directory configuration separate.',1,0),
]
lanes=['Student UI','Node host','SDK + Claude','Hook / Read','Private files'];steps=[];arrows=[]
words=['one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen']
for n,(title,source,anchor,code,explanation,a,b) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');assert anchor in text,(n,anchor)
 anchors=[anchor]+{2:['return { root, cwd: resolve(root, "project"), home: resolve(root, "home"), sdkHome: resolve(root, "sdk-home") };'],4:['if (mode === "project") return ["project"];','if (mode === "combined") return ["user", "project"];','return [];'],6:['return { cwd: dirs.cwd, env: { ...env, HOME: dirs.home, USERPROFILE: dirs.home,'],8:['records.push({','local: process.env.LESSON13_FROM_LOCAL || null,'],9:['counters.callbacks++;']}.get(n,[]);lines=[text[:text.index(a)].count('\n')+1 for a in anchors]
 steps.append(dict(number=n,title=title,source=source,code=code,language='javascript' if source.endswith('.cjs') else 'typescript',explanation=explanation,firstLine=min(lines),lastLine=max(lines),anchors=anchors,sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {words[n-1]}. {explanation} The source label identifies the corresponding application statements.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><title>Lesson 13 setting sources, instructions and hook evidence sequence</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" rx="22" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" font-weight="bold" fill="#101a44">Select sources → load context → observe markers and actual hook traces</text>']
